import { crc32, deflateSync } from "node:zlib";

/**
 * Real images and PDFs for the file pane's specs, made here rather than
 * checked in.
 */

function pngChunk(type: string, data: Buffer): Buffer {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, "latin1"), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([length, body, crc]);
}

/** A PNG: a diagonal colour gradient that fades to transparent on its right. */
export function gradientPng(width: number, height: number): Buffer {
  const header = Buffer.alloc(13);
  header.writeUInt32BE(width, 0);
  header.writeUInt32BE(height, 4);
  header.set([8, 6, 0, 0, 0], 8); // 8-bit RGBA
  const rows: number[] = [];
  for (let y = 0; y < height; y++) {
    rows.push(0); // No row filter.
    for (let x = 0; x < width; x++) {
      const across = x / width;
      const down = y / height;
      rows.push(
        Math.round(255 * across),
        Math.round(120 + 100 * down),
        Math.round(255 * (1 - across)),
        Math.round(255 * Math.min(1, 2 * (1 - across))),
      );
    }
  }
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    pngChunk("IHDR", header),
    pngChunk("IDAT", deflateSync(Buffer.from(rows))),
    pngChunk("IEND", Buffer.alloc(0)),
  ]);
}

type PdfPage = { width: number; height: number; title: string; lines: string[] };

/** A PDF of `pages`: a coloured band, a title and lines of text in Helvetica, not embedded. */
export function simplePdf(pages: PdfPage[]): Buffer {
  const objects: string[] = [];
  const pageRef = (i: number) => 4 + i * 2;
  objects[0] = "<< /Type /Catalog /Pages 2 0 R >>";
  objects[1] = `<< /Type /Pages /Count ${pages.length} /Kids [${pages
    .map((_, i) => `${pageRef(i)} 0 R`)
    .join(" ")}] >>`;
  objects[2] = "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>";
  pages.forEach((page, i) => {
    const text = page.lines
      .map((line, n) => `BT /F1 13 Tf 56 ${page.height - 130 - n * 22} Td (${line}) Tj ET`)
      .join("\n");
    const content = [
      `0.25 0.32 0.85 rg 0 ${page.height - 80} ${page.width} 80 re f`,
      `1 1 1 rg BT /F1 24 Tf 56 ${page.height - 52} Td (${page.title}) Tj ET`,
      "0.1 0.1 0.1 rg",
      text,
    ].join("\n");
    objects[pageRef(i) - 1] =
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${page.width} ${page.height}] ` +
      `/Resources << /Font << /F1 3 0 R >> >> /Contents ${pageRef(i) + 1} 0 R >>`;
    objects[pageRef(i)] = `<< /Length ${content.length} >>\nstream\n${content}\nendstream`;
  });

  let out = "%PDF-1.4\n";
  const offsets = objects.map((body, i) => {
    const offset = out.length;
    out += `${i + 1} 0 obj\n${body}\nendobj\n`;
    return offset;
  });
  const xref = out.length;
  out += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  out += offsets.map((o) => `${String(o).padStart(10, "0")} 00000 n \n`).join("");
  out += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Buffer.from(out, "latin1");
}

/** A 32 × 32 solid red JPEG 2000, as a scanner might store a page (`sips -s format jp2`). */
const RED_JP2 = "";

/** A PDF whose one page is a JPEG 2000 image, filling it: only a decoder can draw it. */
export function jpxPdf(): Buffer {
  const image = Buffer.from(RED_JP2, "base64").toString("latin1");
  const content = "400 0 0 400 0 0 cm /Im0 Do";
  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Count 1 /Kids [3 0 R] >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 400 400] " +
      "/Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>",
    `<< /Type /XObject /Subtype /Image /Width 32 /Height 32 /Filter /JPXDecode /Length ${image.length} >>\nstream\n${image}\nendstream`,
    `<< /Length ${content.length} >>\nstream\n${content}\nendstream`,
  ];
  let out = "%PDF-1.5\n";
  const offsets = objects.map((body, i) => {
    const offset = out.length;
    out += `${i + 1} 0 obj\n${body}\nendobj\n`;
    return offset;
  });
  const xref = out.length;
  out += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  out += offsets.map((o) => `${String(o).padStart(10, "0")} 00000 n \n`).join("");
  out += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Buffer.from(out, "latin1");
}
